import hashlib
import json
from pathlib import Path
import numpy as np
import soundfile as sf
from kokoro import KPipeline
OUT = Path('outputs/mission-set-three')
CLIPS = OUT / 'clips'
CLIPS.mkdir(parents=True, exist_ok=True)
RATE = 24000
CAST = {'ship': ('af_sarah', 0.92), 'captain': ('am_michael', 0.91), 'elena': ('af_heart', 0.9), 'chase': ('am_fenrir', 0.96), 'haven': ('af_bella', 0.92)}
TITLES = {1: 'Beyond Our Galaxy', 2: 'Our Galactic Neighborhood', 3: 'Clusters and Larger Gatherings', 4: 'The Cosmic Web', 5: 'How Far Can We See?'}
SCRIPT = "\n1|all|ship|Signal Operations. Wider universe map available.\n1|all|haven|Hello again, Asterion. We followed your guide from Earth out to the Milky Way. We have reached the last picture, and there is a question beside it. What is beyond our galaxy?\n1|all|captain|Then we have a place to begin. Operator, we will extend the guide. This time, our map will show other galaxies, their neighborhoods, and the larger patterns astronomers have discovered. We will keep a marker for the Milky Way so we can find our way home.\n1|all|elena|The map is changing scale again. A small patch of light may now represent an entire galaxy, with enormous numbers of stars inside it. Earth and the Sun are still there, but they are much too small to draw separately on this view.\n1|all|chase|Here is the Milky Way marker. Around it are other galaxies. Some are large, and some are much smaller. Between them lies intergalactic space. That means the space between galaxies. It contains matter too, although much of it is spread very thinly.\n1|all|elena|It is tempting to imagine that a galaxy has a fence around it. But there is no sign floating in space that says, you are leaving the Milky Way. Its outer regions become more spread out, and different parts extend different distances.\n1|all|chase|One of our large neighbors is Andromeda. Like the Milky Way, it is a spiral galaxy. Its light takes about two and a half million years to reach us. So the light we receive today began its journey long before any person now alive was born.\n1|all|haven|When we see that picture, we are seeing something real, but not something happening at this very moment?\n1|all|chase|That is right. Light carries information, and it takes time to travel. The farther away we look, the older the light reaching us generally is. A telescope collects that arriving light; it cannot make the journey happen instantly.\n1|all|captain|For our first comparison, we have a spiral galaxy and an elliptical galaxy. Operator, choose one to examine more closely.\n1|all|elena|Explore the spiral.\n1|all|elena|Explore the elliptical galaxy.\n1|spiral|chase|The spiral view shows a broad disk and curved arms. Bright young stars can help trace those arms, and darker dust lies between some bright regions. The photograph combines the light of enormous numbers of stars. We are not looking at one object with a solid, painted surface.\n1|elliptical|chase|The elliptical view looks smoother and rounder, or stretched into an oval. It does not show the same clear spiral arms. Much of its light comes from older stars. It is still a galaxy, even though its shape differs from the familiar spiral picture of our own.\n1|all|elena|There are other shapes too, including galaxies called irregular because they do not fit those orderly patterns. We do not need to sort every galaxy today. We have discovered that the universe contains many kinds of galactic homes.\n1|all|ship|Galaxy comparison saved.\n1|all|captain|Next, let us see how some of these galaxies belong together.\n\n2|all|ship|Neighborhood view. The Local Group.\n2|all|chase|The Milky Way and Andromeda are members of a collection called the Local Group. The Triangulum galaxy is another member, along with many smaller galaxies. Local is an astronomer's neighborhood word. These distances are still enormous compared with anything in our everyday lives.\n2|all|elena|On a street map, nearby might mean the next building. On this map, nearby can mean light needs millions of years to cross the gap. The word is familiar, but the size of the neighborhood has changed.\n2|all|captain|Gravity connects the galaxies in a group. They move under one another's influence. They are not fastened to the points where we draw them, and the arrangement will not remain exactly the same forever.\n2|all|haven|Is a group of galaxies the same thing as a group of stars?\n2|all|chase|They are different sizes of structure. A star cluster is a collection of stars. A galaxy group is a collection of galaxies. Each galaxy can contain many star clusters, along with stars spread through its other regions.\n2|all|elena|Our picture labels matter here. If every bright mark looks like a little dot, we could easily mistake one kind of thing for another. Before we compare the dots, we need to know what they stand for.\n2|all|ship|Map labels enabled. Each marked object in this view is a galaxy.\n2|all|chase|Some small galaxies orbit larger ones. We call them satellite galaxies. That does not mean they are machines launched from Earth. Here, satellite describes a relationship: one object traveling around another under gravity.\n2|all|captain|There is also a difference between looking close together and belonging to the same group. Two galaxies might appear beside each other in a photograph while one lies much farther away. Astronomers need more than the flat picture to understand their positions.\n2|all|elena|Like seeing two lights down a road at night. They may look side by side, but one could be near you and the other far beyond it. The view alone does not give you every distance.\n2|all|chase|Astronomers combine measurements of distance and motion with their images. Those measurements help reveal which galaxies share a neighborhood and how that neighborhood behaves. Sometimes new measurements change the map.\n2|all|haven|Then our guide can show what we have learned without pretending the map is finished forever.\n2|all|captain|Exactly. A useful map can improve. Operator, save this neighborhood view with its labels.\n2|all|elena|We have found our galaxy inside a group. But groups are not the only gatherings of galaxies. Our next picture shows a much more crowded collection, and some of what fills it cannot be seen with ordinary light.\n\n3|all|ship|Galaxy cluster view available.\n3|all|chase|This picture shows a galaxy cluster. A cluster can contain hundreds or thousands of galaxies held together by gravity. Some look like bright ovals, others like small smudges. Each one is much more than a single star.\n3|all|elena|A photograph can make a cluster seem tightly packed. But the galaxies are still separated by enormous distances. We are fitting a huge region onto a small display. Close on the screen does not mean close enough for a short trip.\n3|all|captain|Our Local Group is not itself a giant galaxy cluster. We are looking at another kind of neighborhood to understand the larger universe. The nearby Virgo Cluster is one example astronomers study, outside our own group.\n3|all|chase|There is more in a cluster than its galaxies. Very hot, thin gas fills much of the space between them. It gives off X-rays. X-ray telescopes can reveal that gas even when an ordinary visible-light photograph does not show it.\n3|all|elena|Let us add that information to the display. The colored layer tells us where instruments detected the gas. It does not mean a person looking through a window would see a bright cloud in exactly those colors.\n3|all|ship|X-ray information added to the illustration.\n3|all|haven|The same place looks different when we use a different kind of instrument.\n3|all|chase|Yes. Each instrument can reveal something another misses. There is also evidence for a great deal of dark matter in clusters. We infer it from effects such as gravity, rather than seeing it shine like a star. Scientists are still investigating what it is made of.\n3|all|captain|We can be clear about both parts: there is strong evidence for something affecting gravity, and there are important questions about its nature. A question does not make every observation disappear.\n3|all|elena|Now pull back a little farther. Groups and clusters can be parts of much broader arrangements called superclusters. That name can sound like one extra-large cluster, but there is a difference worth keeping.\n3|all|chase|A galaxy cluster is bound together by gravity. A supercluster is a larger arrangement whose parts are generally not all bound together as one object. We should not picture every level as a solid box sitting neatly inside the next box.\n3|all|haven|More like a map that shows relationships at different scales, with different kinds of connections.\n3|all|captain|That is a useful way to put it. Operator, add the cluster view to our guide. Next, we will pull back far enough for another pattern to emerge.\n\n4|all|ship|Large-scale map available. The cosmic web.\n4|all|elena|At first, this picture looks like threads and knots, with large spaces between them. The name scientists use is the cosmic web. It describes a pattern in where matter is gathered across enormous regions of the universe.\n4|all|chase|Galaxies do not spread out perfectly evenly. Many lie along long strands, called filaments, and broad sheets. Dense regions form where parts of that pattern meet. Between them are enormous regions with far fewer galaxies, called voids.\n4|all|captain|The web is not a net made by someone, and the strands are not ropes joining the galaxies. It is a way to describe the distribution of matter. Gravity has helped shape that pattern over billions of years.\n4|all|elena|Our illustration makes the pattern easier to see. It is not a photograph taken by a spacecraft sitting outside the universe. Nobody has that camera position. We build these views from observations, maps, and computer models.\n4|all|chase|A model is something we can compare with measurements. Scientists can ask whether its patterns resemble the universe we observe. When they do not match, that can reveal a problem with the model or something we still need to understand.\n4|all|haven|We would like a picture of the strands and a picture that shows the spaces between them. Can the operator choose which one we look at first?\n4|all|elena|Follow a strand.\n4|all|elena|Explore a void.\n4|strand|chase|We are following a filament on the map. Galaxy markers gather along its length, and the route leads toward a denser region. The bright line helps our eyes follow the pattern. It does not represent a road a spacecraft could drive along.\n4|void|chase|We are looking into a void on the map. There are far fewer galaxy markers here than along the surrounding strands. A void is not necessarily completely empty. Its name describes a region with much less matter than the denser regions around it.\n4|all|elena|Now let us bring both parts back into view. The strands and the less crowded spaces help us recognize the pattern together. Looking only at the brightest knots would leave out much of the shape.\n4|all|captain|Our guide now reaches from one planet to a pattern made from vast numbers of galaxies. Each change of scale has shown something the previous picture could not fit.\n4|all|haven|How far can we keep pulling back? Can we make a picture of absolutely everything?\n4|all|chase|That is where the limits of observation become important. We can map only what we have information about. There is a difference between the whole universe and the part that can send us information.\n4|all|ship|Cosmic web view saved. Final topic available: the observable universe.\n\n5|all|captain|We have reached the widest part of today's guide. Scientists use the phrase observable universe for the region from which light or other signals have had time to reach us since the universe began.\n5|all|elena|Observable means available to observation. It does not mean that every object in that region has already been photographed, or that our telescopes can see every detail. There are things too faint, obscured, or difficult for our instruments to detect.\n5|all|chase|The universe has a history, and light has a travel time. Put those together and there is a limit to how far back and how far away our observations can reach. That limit is not a wall around space.\n5|all|haven|So if a diagram puts a circle around the observable universe, the circle does not mark a solid outer edge?\n5|all|chase|Correct. It marks a limit associated with what can reach an observer. It does not show that Earth sits at the center of the whole universe. An observer in a distant galaxy would have an observable region centered on their own location.\n5|all|elena|There may be much more universe beyond what we can observe. We do not know its total size. Saying that clearly is part of explaining what we know, rather than filling the space beyond our measurements with a made-up answer.\n5|all|captain|There is another important idea. On very large scales, the universe is expanding. Over time, the distances between widely separated galaxies that are not bound together tend to grow.\n5|all|chase|That does not mean Earth is stretching, or that your room grows larger with the universe. Systems held together by gravity or other forces do not simply expand along with those enormous cosmic distances.\n5|all|elena|And our map today is not a movie of that expansion. When we pulled back, we changed the scale of our view. The universe was not suddenly getting bigger each time the display changed.\n5|all|haven|That helps. We have a journey through a map, and the universe also has its own history. Those are different things.\n5|all|captain|They are. Now, Operator, let us return through the places we can name.\n5|all|ship|The cosmic web. Galaxy clusters and groups. Our Local Group. The Milky Way. Our solar system. Earth.\n5|all|elena|Earth is back on the display. The room where you are listening belongs to this world. Our world belongs to a solar system. Our solar system belongs to a galaxy. None of those connections requires us to memorize every name we heard.\n5|all|haven|Your guide has arrived. We can start with home, explore farther, and return when we want to. There are enough questions here for more than one conversation.\n5|all|chase|That is something I like about a good map. It helps me find a place, and sometimes it gives me a reason to wonder about another one.\n5|all|captain|Mission complete. Thank you, Signal Operator.\n5|all|elena|We will leave the final picture at Earth. There is a much larger universe around it, and this is our place within it.\n"
rows = []
for i, line in enumerate(SCRIPT.strip().splitlines(), 1):
    if not line.strip():
        continue
    episode, tag, role, text = line.split('|', 3)
    rows.append({'episode': int(episode), 'tag': tag, 'role': role, 'text': text, 'id': f'line-{i:03d}'})
(OUT / 'script.json').write_text(json.dumps(rows, indent=2, ensure_ascii=False), encoding='utf-8')
readable = []
for episode, title in TITLES.items():
    readable.append(f'\n## {episode}. {title}\n')
    for row in rows:
        if row['episode'] == episode:
            branch = '' if row['tag'] == 'all' else f" [{row['tag']}]"
            readable.append(f"**{row['role'].title()}{branch}:** {row['text']}\n")
(OUT / 'script.md').write_text('\n'.join(readable), encoding='utf-8')
pipeline = KPipeline(lang_code='a', device='cpu')
for index, row in enumerate(rows, 1):
    voice, speed = CAST[row['role']]
    key = hashlib.sha256(json.dumps([voice, speed, row['text']]).encode()).hexdigest()[:16]
    path = CLIPS / f"ep{row['episode']}-{row['id']}-{row['role']}-{key}.wav"
    valid = False
    if path.exists():
        try:
            samples, rate = sf.read(path, dtype='float32')
            valid = rate == RATE and samples.size > 0 and np.isfinite(samples).all() and (np.max(np.abs(samples)) > 0)
        except Exception:
            pass
    if not valid:
        print(f"[{index}/{len(rows)}] Episode {row['episode']}: {row['role']}", flush=True)
        chunks = []
        for _, _, audio in pipeline(row['text'], voice=voice, speed=speed):
            if audio is not None:
                if hasattr(audio, 'detach'):
                    audio = audio.detach().cpu().numpy()
                chunks.append(np.asarray(audio, dtype=np.float32))
        if not chunks:
            raise RuntimeError(f"No audio for {row['id']}")
        samples = np.concatenate(chunks)
        if not np.isfinite(samples).all() or np.max(np.abs(samples)) == 0:
            raise RuntimeError(f"Invalid audio for {row['id']}")
        temp = path.with_suffix('.tmp.wav')
        sf.write(temp, samples, RATE, subtype='PCM_16')
        temp.replace(path)
    else:
        print(f"[{index}/{len(rows)}] Reusing {row['id']}", flush=True)
    row['file'] = str(path)
    row['seconds'] = len(samples) / RATE
routes = {'main': {'all', 'strand', 'spiral'}, 'alternate': {'all', 'void', 'elliptical'}}
gap = np.zeros(int(RATE * 0.55), dtype=np.float32)
between = np.zeros(RATE * 2, dtype=np.float32)
report = ['SET THREE: THE WIDER UNIVERSE']
for route, tags in routes.items():
    total = 0
    transcript = []
    with sf.SoundFile(OUT / f'full-listening-draft-{route}.wav', mode='w', samplerate=RATE, channels=1, subtype='PCM_16') as full:
        for episode, title in TITLES.items():
            transcript.append(f'\n## {episode}. {title}\n')
            selected = [row for row in rows if row['episode'] == episode and row['tag'] in tags]
            seconds = 0
            with sf.SoundFile(OUT / f'episode-{episode:02d}-{route}.wav', mode='w', samplerate=RATE, channels=1, subtype='PCM_16') as track:
                for row in selected:
                    samples, _ = sf.read(row['file'], dtype='float32')
                    track.write(samples)
                    track.write(gap)
                    full.write(samples)
                    full.write(gap)
                    seconds += len(samples) / RATE + 0.55
                    transcript.append(f"**{row['role'].title()}:** {row['text']}\n")
            full.write(between)
            total += seconds + 2
            report.append(f'{route}: episode {episode}: {int(seconds // 60)}m {int(seconds % 60):02d}s')
    report.append(f'{route}: TOTAL {int(total // 60)}m {int(total % 60):02d}s')
    (OUT / f'transcript-{route}.md').write_text('\n'.join(transcript), encoding='utf-8')
(OUT / 'manifest.json').write_text(json.dumps(rows, indent=2, ensure_ascii=False), encoding='utf-8')
report.extend([f'Generated or reused {len(rows)} dialogue clips.', 'Audio review only; illustrations are not generated.', 'Timings exclude player response delays and unvisited branches.', f'Output folder: {OUT.resolve()}'])
(OUT / 'timing-report.txt').write_text('\n'.join(report), encoding='utf-8')
print('\nSUCCESS\n' + '\n'.join(report), flush=True)
